export class ParserRegistry {
  private map = new Map<string, Parser>();
  register(format: string, p: Parser) { this.map.set(format, p) }
  get(format: string): Parser {
    const p = this.map.get(format)
    if (!p) throw new Error(`Unknown format: ${format}`)
    return p
  }
}
